            else:
                if len(cur)>0: sepcols.append((cur[0],cur[-1]))
                cur=[]
        if len(cur)>0: sepcols.append((cur[0],cur[-1]))
        # separator columns mark tile boundaries; tile = run of nonzero cols between separators
        # scan each row; an "anomalous" cell (nonzero != most common nonzero in band) extends to fill adjacent zeros
